/**
 * generated by stackra gen from src/config/env.config.ts (WebEnv), runway.yaml
 * (environments.<env>.vars, secrets) — do not edit
 * Purpose: types `import.meta.env` from the class's public (`VITE_`) fields and the Worker `Env`
 *          from its server fields plus the secret names; gen appends the Workers runtime
 *          declarations `wrangler types` emits for the compatibility date (`ExecutionContext`,
 *          `Fetcher`, `caches`), so the Worker entry type-checks without a types package. Code
 *          reads the validated objects from `#stackra/env`, not these.
 * Boundary: types only; code reads the validated objects from `#stackra/env`.
 * Runtime: isomorphic
 */
interface ImportMetaEnv {
  readonly VITE_POSTHOG_KEY?: string;
  readonly VITE_TURNSTILE_SITE_KEY?: string;
}
interface ImportMeta {
  readonly env: ImportMetaEnv;
}

/**
 * The Worker's bindings: server vars, secrets (by name; values synced by runway) and the assets
 * binding. `entry/worker.ts` reads only `STACKRA_SITE_URL` raw, for its host guard; everything else
 * is read through the validated `serverEnv`.
 */
interface Env {
  readonly STACKRA_API_URL: string;
  readonly STACKRA_SITE_URL: string;
  readonly STACKRA_SENTRY_DSN: string;
  readonly TURNSTILE_SECRET_KEY: string;
  readonly GATEWAY_VISITOR_SIGNING_KEY: string;
  readonly ASSETS: Fetcher;
}
